






















import { Vue, Component, Prop, Watch } from 'vue-property-decorator'
import { getOrderDetailPage } from '@/api/order'

@Component({
  name: 'TabChange',
})
export default class extends Vue {
  @Prop({ default: '' }) orderStatics: any
  @Prop({ default: '' }) defaultActivity: any
  private activeIndex: number = this.defaultActivity || 2 // 2 是等待商家接单

  @Watch('defaultActivity')
  private onChange(val) {
    this.activeIndex = Number(val)
  }

  get changedOrderList() {
    return [
      {
        label: '等待商家接单',
        value: 2,
        num: this.orderStatics.waiting4MerchantReceiveOrders,
      },
      {
        label: '等待骑手接单',
        value: 3,
        num: this.orderStatics.waitng4RiderReceiveOrders,
      },
      {
        label: '待出餐',
        value: 4,
        num: this.orderStatics.toBeDeliveryOnProgressOrders,
      },
      {
        label: '待送达',
        value: 5,
        num: this.orderStatics.toBeArrivedOrders,
      },
      {
        label: '已取消',
        value: 7,
        num: this.orderStatics.canceledOrders,
      },
      {
        label: '已完成',
        value: 6,
        num: this.orderStatics.completedOrders,
      },
      {
        label: '全部订单',
        value: 0,
      },
    ]
  }

  private tabChange(activeIndex) {
    this.activeIndex = activeIndex
    this.$emit('tabChange', activeIndex)
  }
}
